s=dict(id='q-1025',subject='Civics',title='嬸嬸和姊夫是姻親，不是旁系血親',art=str(art.relative_to(R)),layoutVersion='native-fluid-v6',generationMethod='new selectable HTML kinship paths and precise parent/spouse relationship analysis',sourceGeneratedArtUsed=False,originalMaterialsChecked=True,originalMaterials=['site/dist/assets/questions/q-1025-original-16-092caf96cbbd.jpg','site/dist/assets/questions/q-1025-figure-16-c16c683323a0.jpg'],sourceReview='correction-q-1025-5ea0c491b56e (resolved)',answerCheckedAgainst='重新實看五經理名單為名凱、媽媽、嬸嬸、爸爸、姊夫，並讀已resolved確認。無一對旁系血親，B；不把嬸嬸改姑姑，也不把姊夫當嬸嬸的配偶。',supportingSources=[dict(title='民法第967條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=967',finding='直系血親依世代所出；旁系血親是同源但非直系的血親。'),dict(title='民法第969條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=969',finding='血親的配偶、配偶的血親、配偶的血親的配偶，屬姻親。')],rationale='本題易錯在稱謂所指的精確婚姻與血緣連結，不是家人外貌或辦公室情境。用可選取中文關係路徑直接標人名、關係、三種人數，避免生成人像誤連嬸嬸與姊夫；沒有把名單外叔叔姊姊加入經理數。',panels=[dict(heading='① 直系血親涉及名凱和爸媽三人',text='名凱與爸爸、媽媽分別是直系血親。爸爸和媽媽彼此是一組配偶，不是因為同為家人就彼此成為血親。',alt='爸爸與名凱、媽媽與名凱分別直系血親的可選取路徑，合計三位名單內人物。',diagram=dict(kind='paths',title='把直系血親配對列出',items=[dict(label='爸爸 ↔ 名凱',detail='親子，直系血親。',tone='blue'),dict(label='媽媽 ↔ 名凱',detail='親子，直系血親。',tone='green')],target='涉及3人，不是C所說的4人',arrow='只計不同的人，不重複算名凱',note='名單內配偶只有爸爸、媽媽一組，A也不成立。')),dict(heading='② 嬸嬸、姊夫都由婚姻連結',text='嬸嬸是叔叔的配偶；姊夫是姊姊的配偶。兩者與名凱均是姻親，不能因稱謂帶親屬字，就當成旁系血親。',alt='嬸嬸連到叔叔配偶、姊夫連到姊姊配偶，兩者與名凱均由婚姻連結而為姻親。',diagram=dict(kind='paths',title='逐字拆開親屬稱謂',items=[dict(label='嬸嬸＝叔叔的配偶',detail='不是爸爸的姊妹。',tone='gold'),dict(label='姊夫＝姊姊的配偶',detail='不是名凱的親姊姊。',tone='blue')],target='名凱與兩人均是姻親',arrow='從婚姻關係連結',note='叔叔、姊姊只用來解釋稱謂，沒有列在五位經理內。')),dict(heading='③ 五人都可找到姻親配對',text='名凱與姊夫、爸媽與姊夫，以及嬸嬸與名凱，都有姻親連結。這涵蓋名單五人，所以D說姻親人數最少也不對。',alt='名凱與姊夫、爸媽與姊夫、嬸嬸與名凱三組可選取配對，涵蓋名單全五人。',diagram=dict(kind='paths',title='檢查D，不把姻親只算兩人',items=[dict(label='名凱 ↔ 姊夫',detail='血親的配偶。',tone='blue'),dict(label='爸爸、媽媽 ↔ 姊夫',detail='女兒的配偶。',tone='green'),dict(label='嬸嬸 ↔ 名凱',detail='配偶的血親。',tone='gold')],target='五人均可找到姻親配對',arrow='同一人可對不同人有不同關係'))],fourth=dict(answer='答案 B：沒有旁系血親配對',points=['只比較原圖列出的五位經理。','爸爸媽媽是一組配偶；名凱和爸媽涉及直系血親三人。','嬸嬸、姊夫是姻親；不能改成姑姑、姊姊。']),protectedWords=['名凱','嬸嬸','姊夫','直系血親','旁系血親','姻親','叔叔','姊姊','五位經理'],createdAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),artSHA256=hashlib.sha256(svg.encode()).hexdigest())
